const slides=[...document.querySelectorAll('.slide')];let current=0;function show(i){current=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,idx)=>s.classList.toggle('active',idx===current));document.getElementById('bar').style.width=((current+1)/slides.length*100)+'%';location.hash='s'+(current+1)}function fromHash(){const m=location.hash.match(/s(\d+)/);if(m)show(parseInt(m[1],10)-1);else show(0)}document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});window.addEventListener('hashchange',fromHash);fromHash();